// The Killswitch mark and wordmark. Geometry lives in brand-geometry.ts, generated by a script:
// the mark is fitted to the supplied logo PNG (rounded ring with a gap, and a bar through it);
// the wordmark is "KILLSWITCH" in Inter Bold converted to outlines.
import { MARK, WORDMARK } from "./brand-geometry";

export function Mark({ className = "", title }: { className?: string; title?: string }) {
  return (
    <svg className={`mark ${className}`} viewBox={MARK.viewBox} role={title ? "img" : undefined} aria-hidden={title ? undefined : true}>
      {title && <title>{title}</title>}
      <path className="mark-ring" d={MARK.ring} />
      <path className="mark-bar" d={MARK.bar} />
    </svg>
  );
}

export function Wordmark({ className = "" }: { className?: string }) {
  return (
    <svg className={`wordmark ${className}`} viewBox={WORDMARK.viewBox} aria-hidden="true">
      <path d={WORDMARK.path} />
    </svg>
  );
}

/** Mark and wordmark side by side, sharing a baseline. */
export function Logo({ className = "" }: { className?: string }) {
  return (
    <span className={`logo ${className}`}>
      <Mark />
      <Wordmark />
      <span className="sr-only">Killswitch</span>
    </span>
  );
}
